import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

// ─────────────────────────────────────────────────────────────
// Pack identity
//   Category : mobile native — navigation / checkpoint alerts
//   Pack     : industry-mobile-android (M3 Expressive) + iOS
//   Tone     : serious-precise — real-world safety data
//   Density  : platform-native (48dp tap targets, 64dp nav bar)
//   Accent   : fixed brand blue — Material You dynamic color
//              intentionally OFF; wallpaper-derived hues would
//              conflict with status semantics (red=active,
//              green=clear, amber=police alert).
// ─────────────────────────────────────────────────────────────

// ─── Fonts ────────────────────────────────────────────────────

abstract final class ThemeFonts {
  static const String ui = 'Inter';
  static const String display = 'Poppins';
}

// ─── Raw palette (private) ────────────────────────────────────
// Components never read these directly — use ThemeColors.

abstract final class _Palette {
  // Neutral — desaturated blue-gray, not pure gray
  static const Color n0   = Color(0xFFFFFFFF);
  static const Color n50  = Color(0xFFF7F8FA);
  static const Color n100 = Color(0xFFEFF1F5);
  static const Color n150 = Color(0xFFE8EBF0);
  static const Color n200 = Color(0xFFE1E4EB);
  static const Color n300 = Color(0xFFC8CDD7);
  static const Color n400 = Color(0xFFADB3BE);
  static const Color n500 = Color(0xFF8C939F);
  static const Color n600 = Color(0xFF5A6270);
  static const Color n700 = Color(0xFF414955);
  static const Color n800 = Color(0xFF2B313A);
  static const Color n900 = Color(0xFF161A20);

  // Brand blue
  static const Color b50  = Color(0xFFEBEFFB);
  static const Color b100 = Color(0xFFD2DCF7);
  static const Color b200 = Color(0xFFA8BCEF);
  static const Color b500 = Color(0xFF2563EB); // ★ accent
  static const Color b600 = Color(0xFF1D4ED8);
  static const Color b700 = Color(0xFF1E40AF);

  // Status — semantic only, never branded
  static const Color green500 = Color(0xFF16A34A);
  static const Color green50  = Color(0xFFF0FDF4);
  static const Color green100 = Color(0xFFDCFCE7);
  static const Color amber600 = Color(0xFFD97706);
  static const Color amber50  = Color(0xFFFFFBEB);
  static const Color amber100 = Color(0xFFFEF3C7);
  static const Color red500   = Color(0xFFDC2626);
  static const Color red50    = Color(0xFFFEF2F2);
  static const Color red100   = Color(0xFFFEE2E2);

  // Domain
  static const Color plate = Color(0xFFFFD307);
}

// ─── Semantic tokens ──────────────────────────────────────────
// Use these everywhere. Naming follows M3 roles where they apply.

abstract final class ThemeColors {
  // ── Surfaces ──
  static const Color bg                   = _Palette.n50;   // page background
  static const Color surface              = _Palette.n0;    // card / raised
  static const Color surfaceContainer     = _Palette.n100;  // subtle tinted
  static const Color surfaceContainerHigh = _Palette.n150;  // hover bg

  // ── Borders / outline ──
  static const Color border       = _Palette.n200;
  static const Color borderStrong = _Palette.n300;
  static const Color outline      = _Palette.n400; // M3 outline role

  // ── Text ──
  static const Color textPrimary   = _Palette.n900;
  static const Color textSecondary = _Palette.n600;
  static const Color textTertiary  = _Palette.n500;
  static const Color textDisabled  = _Palette.n400;

  // ── Accent (primary) ──
  static const Color accent        = _Palette.b500;
  static const Color accentStrong  = _Palette.b600;
  static const Color accentSubtle  = _Palette.b50;

  // ── Secondary (neutral, co-equal) ──
  static const Color secondary            = _Palette.n700;
  static const Color secondaryContainer   = _Palette.n100;
  static const Color onSecondaryContainer = _Palette.n800;

  // ── Status — semantic, never branded ──
  static const Color success       = _Palette.green500;
  static const Color successSubtle = _Palette.green50;
  static const Color successTint   = _Palette.green100;
  static const Color warning       = _Palette.amber600;
  static const Color warningSubtle = _Palette.amber50;
  static const Color warningTint   = _Palette.amber100;
  static const Color danger        = _Palette.red500;
  static const Color dangerSubtle  = _Palette.red50;
  static const Color dangerTint    = _Palette.red100;
  static const Color info          = accent;
  static const Color infoSubtle    = accentSubtle;

  // ── Domain ──
  static const Color plateYellow = _Palette.plate;

  // ── Legacy aliases — keep while call-sites migrate ──
  static const Color bgRaised    = surface;
  static const Color bgSubtle    = surfaceContainer;
  static const Color stone50     = bg;
  static const Color stone100    = surface;
  static const Color stone200    = _Palette.n200;
  static const Color stone300    = _Palette.n300;
  static const Color stone400    = _Palette.n400;
  static const Color stone500    = _Palette.n500;
  static const Color stone600    = _Palette.n600;
  static const Color stone700    = _Palette.n700;
  static const Color stone800    = _Palette.n800;
  static const Color stone900    = _Palette.n900;
  static const Color slate50     = accentSubtle;
  static const Color slate100    = _Palette.b100;
  static const Color slate500    = accent;
  static const Color slate600    = accentStrong;
  static const Color accentHover = accentStrong;
}

// ─── Spacing ──────────────────────────────────────────────────
// 4dp base. sp4 = 16dp screen edge — sacred.

abstract final class ThemeSpacing {
  static const double sp0  = 0;
  static const double sp1  = 4;
  static const double sp2  = 8;
  static const double sp3  = 12;
  static const double sp4  = 16; // ★ screen edge
  static const double sp5  = 20;
  static const double sp6  = 24;
  static const double sp8  = 32;
  static const double sp10 = 40;
  static const double sp12 = 48;
  static const double sp16 = 64;
}

// ─── Shape system ─────────────────────────────────────────────
// M3 Expressive shape scale (dp):
//   extraSmall=4  small=8  medium=12  large=16  extraLarge=28  full
// Components pick the corner size matching their role:
//   inputs/snackbars → extraSmall
//   cards            → medium
//   modals / sheets  → extraLarge (28dp top corners)
//   buttons / chips  → full (pill)

abstract final class ThemeRadius {
  // M3 shape tokens
  static const double extraSmall = 4;
  static const double small      = 8;
  static const double medium     = 12;
  static const double large      = 16;
  static const double extraLarge = 28;
  static const double full       = 9999;

  static final BorderRadius brExtraSmall = BorderRadius.circular(extraSmall);
  static final BorderRadius brSmall      = BorderRadius.circular(small);
  static final BorderRadius brMedium     = BorderRadius.circular(medium);
  static final BorderRadius brLarge      = BorderRadius.circular(large);
  static final BorderRadius brExtraLarge = BorderRadius.circular(extraLarge);
  static final BorderRadius brFull       = BorderRadius.circular(full);

  // Sheet top-corners only (M3 modal bottom sheet spec: 28dp)
  static const BorderRadius brSheet = BorderRadius.only(
    topLeft:  Radius.circular(extraLarge),
    topRight: Radius.circular(extraLarge),
  );

  // Legacy aliases — keep while call-sites migrate
  static const double rXs  = extraSmall;
  static const double rSm  = 6;          // off-scale; use extraSmall or small
  static const double rMd  = small;
  static const double rLg  = medium;
  static const double rXl  = large;
  static const double r2xl = 22;         // pre-M3 value; prefer extraLarge
  static const double rFull = full;
  static final BorderRadius brXs  = brExtraSmall;
  static final BorderRadius brSm  = BorderRadius.circular(6);
  static final BorderRadius brMd  = brSmall;
  static final BorderRadius brLg  = brMedium;
  static final BorderRadius brXl  = brLarge;
  static final BorderRadius br2xl = BorderRadius.circular(22);
}

// ─── Elevation / shadows ──────────────────────────────────────
// Shadows signal depth, not decoration.
// 0 → use background contrast or outline instead of shadow
// pop     → hover cards, floating map buttons
// overlay → dropdowns, popovers, autocomplete
// modal   → bottom sheets, dialogs

abstract final class ThemeShadows {
  static const List<BoxShadow> pop = [
    BoxShadow(blurRadius: 2, offset: Offset(0, 1), color: Color(0x0F161A20)),
    BoxShadow(blurRadius: 8, offset: Offset(0, 4), color: Color(0x09161A20)),
  ];
  static const List<BoxShadow> overlay = [
    BoxShadow(blurRadius: 8,  offset: Offset(0, 2), color: Color(0x14161A20)),
    BoxShadow(blurRadius: 20, offset: Offset(0, 8), color: Color(0x0D161A20)),
  ];
  static const List<BoxShadow> modal = [
    BoxShadow(blurRadius: 32, offset: Offset(0, -4), color: Color(0x1A161A20)),
    BoxShadow(blurRadius: 8,  offset: Offset(0,  2), color: Color(0x10161A20)),
  ];

  // Legacy aliases
  static const List<BoxShadow> sm = pop;
  static const List<BoxShadow> md = overlay;
  static const List<BoxShadow> lg = modal;
}

// ─── Motion ───────────────────────────────────────────────────
// M3 Expressive: springs for meaningful state changes,
// easing for enter/exit.
//
// Emil Kowalski's rule: only animate what changes meaning.
// Anything triggered >50×/session should be instant.
//
// Duration budget per interaction tier:
//   instant (0)    keyboard, Esc, frequent nav tabs
//   fast   (100)   hover, focus ring, color change, opacity
//   normal (200)   enter/exit, dropdown, optimistic confirm
//   medium (300)   modal/sheet enter, route reveal
//   slow   (400)   map route draw, complex state change

abstract final class ThemeMotion {
  // ── Named durations ──
  static const Duration instant = Duration(milliseconds: 0);
  static const Duration fast    = Duration(milliseconds: 100);
  static const Duration normal  = Duration(milliseconds: 200);
  static const Duration medium  = Duration(milliseconds: 300);
  static const Duration slow    = Duration(milliseconds: 400);

  // M3 granular scale — use only when fine control is needed
  static const Duration short1  = Duration(milliseconds: 50);
  static const Duration short2  = Duration(milliseconds: 100); // = fast
  static const Duration short3  = Duration(milliseconds: 150);
  static const Duration short4  = Duration(milliseconds: 200); // = normal
  static const Duration medium1 = Duration(milliseconds: 250);
  static const Duration medium2 = Duration(milliseconds: 300); // = medium
  static const Duration medium3 = Duration(milliseconds: 350);
  static const Duration medium4 = Duration(milliseconds: 400); // = slow
  static const Duration long1   = Duration(milliseconds: 450);
  static const Duration long2   = Duration(milliseconds: 500);

  // ── Easing curves ──
  // Enter: decelerate into final position (elements arriving)
  static const Curve easeOut = Cubic(0.16, 1.0, 0.3, 1.0);

  // Exit: accelerate away (elements leaving)
  static const Curve easeIn = Cubic(0.4, 0.0, 1.0, 1.0);

  // Bidirectional / data transitions / color: M3 Standard + Grain fluid
  static const Curve smooth = Cubic(0.2, 0.0, 0.0, 1.0);

  // M3 emphasized — important cross-screen transitions
  static const Curve emphasized = Cubic(0.2, 0.0, 0.0, 1.0);

  // Snappy — fast feedback: button press, chip select, toggle
  static const Curve snappy = Cubic(0.2, 0.0, 0.0, 1.0);

  // Spring — drag/gesture release, FAB expand, physical interactions.
  // Sparingly — not for critical-path or high-frequency actions.
  static const Curve spring = Cubic(0.34, 1.56, 0.64, 1.0);

  // Legacy aliases
  static const Duration durFast   = fast;
  static const Duration durBase   = normal;
  static const Duration durSlow   = medium;
  static const Duration durSlower = slow;
}

// ─── Text styles ──────────────────────────────────────────────
// M3 15-token scale mapped to Inter (UI) + Poppins (display).
// Bold over Big: weight drives hierarchy, not font size jumps.
// All const — enables const widget constructors throughout.
//
// Scale:
//   Display  (Poppins) — product moments, onboarding, empty states
//   Headline (Inter)   — screen titles, section headers
//   Title    (Inter)   — cards, dialog headers, list sections
//   Body     (Inter)   — all body copy; 15sp minimum on mobile
//   Label    (Inter)   — buttons, tabs, chips, captions

abstract final class ThemeText {
  // ── Display ──
  static const TextStyle displayLarge = TextStyle(
    fontFamily: ThemeFonts.display,
    fontSize: 32,
    fontWeight: FontWeight.w700,
    height: 1.15,
    letterSpacing: -0.5,
    color: ThemeColors.textPrimary,
  );
  static const TextStyle displayMedium = TextStyle(
    fontFamily: ThemeFonts.display,
    fontSize: 26,
    fontWeight: FontWeight.w600,
    height: 1.2,
    letterSpacing: -0.3,
    color: ThemeColors.textPrimary,
  );
  static const TextStyle displaySmall = TextStyle(
    fontFamily: ThemeFonts.display,
    fontSize: 22,
    fontWeight: FontWeight.w600,
    height: 1.25,
    letterSpacing: -0.2,
    color: ThemeColors.textPrimary,
  );

  // ── Headline ──
  static const TextStyle headlineLarge = TextStyle(
    fontFamily: ThemeFonts.ui,
    fontSize: 24,
    fontWeight: FontWeight.w600,
    height: 1.25,
    letterSpacing: -0.2,
    color: ThemeColors.textPrimary,
  );
  static const TextStyle headlineMedium = TextStyle(
    fontFamily: ThemeFonts.ui,
    fontSize: 20,
    fontWeight: FontWeight.w600,
    height: 1.3,
    letterSpacing: -0.1,
    color: ThemeColors.textPrimary,
  );
  static const TextStyle headlineSmall = TextStyle(
    fontFamily: ThemeFonts.ui,
    fontSize: 18,
    fontWeight: FontWeight.w500,
    height: 1.3,
    color: ThemeColors.textPrimary,
  );

  // ── Title ──
  static const TextStyle titleLarge = TextStyle(
    fontFamily: ThemeFonts.ui,
    fontSize: 17,
    fontWeight: FontWeight.w600,
    height: 1.35,
    color: ThemeColors.textPrimary,
  );
  static const TextStyle titleMedium = TextStyle(
    fontFamily: ThemeFonts.ui,
    fontSize: 15,
    fontWeight: FontWeight.w500,
    height: 1.4,
    letterSpacing: 0.1,
    color: ThemeColors.textPrimary,
  );
  static const TextStyle titleSmall = TextStyle(
    fontFamily: ThemeFonts.ui,
    fontSize: 13,
    fontWeight: FontWeight.w500,
    height: 1.4,
    letterSpacing: 0.1,
    color: ThemeColors.textPrimary,
  );

  // ── Body (15sp minimum) ──
  static const TextStyle bodyLarge = TextStyle(
    fontFamily: ThemeFonts.ui,
    fontSize: 16,
    fontWeight: FontWeight.w400,
    height: 1.5,
    color: ThemeColors.textPrimary,
  );
  static const TextStyle bodyMedium = TextStyle(
    fontFamily: ThemeFonts.ui,
    fontSize: 15,
    fontWeight: FontWeight.w400,
    height: 1.5,
    color: ThemeColors.textPrimary,
  );
  static const TextStyle bodySmall = TextStyle(
    fontFamily: ThemeFonts.ui,
    fontSize: 13,
    fontWeight: FontWeight.w400,
    height: 1.45,
    color: ThemeColors.textSecondary,
  );

  // ── Label (for interactive elements) ──
  static const TextStyle labelLarge = TextStyle(
    fontFamily: ThemeFonts.ui,
    fontSize: 14,
    fontWeight: FontWeight.w500,
    height: 1.4,
    letterSpacing: 0.1,
    color: ThemeColors.textPrimary,
  );
  static const TextStyle labelMedium = TextStyle(
    fontFamily: ThemeFonts.ui,
    fontSize: 12,
    fontWeight: FontWeight.w500,
    height: 1.4,
    letterSpacing: 0.4,
    color: ThemeColors.textSecondary,
  );
  static const TextStyle labelSmall = TextStyle(
    fontFamily: ThemeFonts.ui,
