/// Visible state of the bottom sheet.
enum SheetMode {
  /// Collapsed — "Where to?" pill visible, map is primary.
  peek,

  /// Fully expanded — origin + destination inputs, autosuggest list.
  fullSearch,

  /// Half-open — trip summary card, route checkpoints, Start drive CTA.
  tripOverview,
}

/// Persistent sheet UI state.
///
/// Lives outside the widget tree so peeking / collapsing the sheet
/// never discards typed text, scroll position, or suggestions.
class SheetState {
  final SheetMode mode;

  /// Text in the origin field (may be empty if using current location).
  final String typedOrigin;

  /// Text in the destination field (what the user has typed so far).
  final String typedDest;

  const SheetState({
    this.mode = SheetMode.peek,
    this.typedOrigin = '',
    this.typedDest = '',
  });

  SheetState copyWith({
    SheetMode? mode,
    String? typedOrigin,
    String? typedDest,
  }) =>
      SheetState(
        mode: mode ?? this.mode,
        typedOrigin: typedOrigin ?? this.typedOrigin,
        typedDest: typedDest ?? this.typedDest,
      );
}

import 'package:here_sdk/routing.dart';

/// Camera ownership during an active drive.
enum CameraOwnership {
  /// HERE SDK owns the camera — auto-follows, auto-zooms around turns.
  following,

  /// User has panned the map — camera is released (`cameraBehavior = null`).
  /// Arrow and all data updates continue; only the view has wandered.
  free,
}

/// The top-level navigation state machine.
///
/// Every screen that renders navigation UI switches on this.
/// Transitions happen only through NavStateNotifier — never mutated directly.
sealed class NavigationPhase {
  const NavigationPhase();
}

/// No route, no search — the default idle state.
final class Idle extends NavigationPhase {
  const Idle();
}

/// Autosuggest is running while the user types a destination.
final class Searching extends NavigationPhase {
  const Searching();
}

/// Route has been computed. Sheet is half-open at trip overview.
final class TripOverview extends NavigationPhase {
  final Route route;

  /// True while the async route-checkpoint filter is still running.
  final bool checkpointsLoading;

  const TripOverview({
    required this.route,
    this.checkpointsLoading = true,
  });

  TripOverview copyWith({Route? route, bool? checkpointsLoading}) =>
      TripOverview(
        route: route ?? this.route,
        checkpointsLoading: checkpointsLoading ?? this.checkpointsLoading,
      );
}

/// Turn-by-turn guidance is active.
final class ActiveDrive extends NavigationPhase {
  final Route route;
  final CameraOwnership camera;

  /// True while a silent reroute is in progress.
  final bool isRerouting;

  const ActiveDrive({
    required this.route,
    this.camera = CameraOwnership.following,
    this.isRerouting = false,
  });

  ActiveDrive copyWith({
    Route? route,
    CameraOwnership? camera,
    bool? isRerouting,
  }) =>
      ActiveDrive(
        route: route ?? this.route,
        camera: camera ?? this.camera,
        isRerouting: isRerouting ?? this.isRerouting,
      );
}

import 'package:here_sdk/core.dart';
import 'package:here_sdk/navigation.dart';
import 'package:here_sdk/routing.dart';
import 'package:here_sdk/transport.dart';

// Single file that owns UK-imperial configuration for routing and navigation.
// UnitSystem.imperialUk is the exact identifier — the lowercase 'k' matters.
// This is the ONLY place in the codebase that references UnitSystem.imperialUk.
//
// CarOptions / PedestrianOptions are deprecated since SDK 4.28.0.
// The replacement is RoutingOptions with TransportSpecification.

/// Returns [RoutingOptions] for car routing with UK imperial units.
RoutingOptions buildUkCarOptions() {
  final options = RoutingOptions();
  // Default transport mode is already TransportMode.car — no change needed.
  options.textOptions.language = LanguageCode.enGb;
  options.textOptions.unitSystem = UnitSystem.imperialUk;
  return options;
}

/// Returns [RoutingOptions] for pedestrian routing with UK imperial units.
RoutingOptions buildUkPedestrianOptions() {
  final options = RoutingOptions();
  options.transportSpecification.transportMode = TransportMode.pedestrian;
  options.textOptions.language = LanguageCode.enGb;
  options.textOptions.unitSystem = UnitSystem.imperialUk;
  return options;
}

/// Sets UK imperial units on [navigator]'s voice/text notifications.
///
/// Call once immediately after constructing the [VisualNavigator].
/// Must be called again if the navigator is ever recreated.
void applyUkUnitsToNavigator(VisualNavigator navigator) {
  final opts = ManeuverNotificationOptions.withDefaults();
  opts.language = LanguageCode.enGb;
  opts.unitSystem = UnitSystem.imperialUk;
  navigator.maneuverNotificationOptions = opts;
}

