import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:ukcheckpoints_app/core/theme/theme.dart';
import 'package:ukcheckpoints_app/features/navigation/models/sheet_state.dart';
import 'package:ukcheckpoints_app/features/navigation/providers/sheet_state_provider.dart';
import 'package:ukcheckpoints_app/features/navigation/sheets/full_search_content.dart';
import 'package:ukcheckpoints_app/features/navigation/sheets/peek_content.dart';

const double kMapSheetMinExtent  = 0.12;
const double kMapSheetMidExtent  = 0.50;
const double kMapSheetMaxExtent  = 0.92;

// Tolerance for snapped-position detection from the controller listener.
const double _snapTol = 0.02;

class MapBottomSheet extends ConsumerStatefulWidget {
  const MapBottomSheet({super.key});

  @override
  ConsumerState<MapBottomSheet> createState() => _MapBottomSheetState();
}

class _MapBottomSheetState extends ConsumerState<MapBottomSheet> {
  final _controller = DraggableScrollableController();

  @override
  void initState() {
    super.initState();
    _controller.addListener(_onControllerChanged);
  }

  @override
  void dispose() {
    _controller
      ..removeListener(_onControllerChanged)
      ..dispose();
    super.dispose();
  }

  // ── Drag → provider sync ──────────────────────────────────────────────────
  // When the user manually drags the sheet to a snap point, mirror that into
  // the provider so the rendered content stays correct.
  void _onControllerChanged() {
    if (!_controller.isAttached) return;
    final s = _controller.size;
    final notifier = ref.read(sheetStateNotifierProvider.notifier);
    if ((s - kMapSheetMinExtent).abs() < _snapTol) {
      notifier.peek();
    } else if ((s - kMapSheetMaxExtent).abs() < _snapTol) {
      notifier.expand();
    } else if ((s - kMapSheetMidExtent).abs() < _snapTol) {
      notifier.showTripOverview();
    }
  }

  // ── Provider → animation ──────────────────────────────────────────────────
  Future<void> _animateTo(double extent) async {
    if (!_controller.isAttached) return;
    if ((_controller.size - extent).abs() < _snapTol) return;
    await _controller.animateTo(
      extent,
      duration: ThemeMotion.medium,
      curve: ThemeMotion.smooth,
    );
  }

  void _onExpand() {
    ref.read(sheetStateNotifierProvider.notifier).expand();
    unawaited(_animateTo(kMapSheetMaxExtent));
  }

  // ── Build ─────────────────────────────────────────────────────────────────

  @override
  Widget build(BuildContext context) {
    // Drive sheet animation whenever the provider mode changes.
    ref.listen<SheetState>(sheetStateNotifierProvider, (prev, next) {
      if (prev?.mode == next.mode) return;
      switch (next.mode) {
        case SheetMode.peek:
          unawaited(_animateTo(kMapSheetMinExtent));
        case SheetMode.fullSearch:
          unawaited(_animateTo(kMapSheetMaxExtent));
        case SheetMode.tripOverview:
          unawaited(_animateTo(kMapSheetMidExtent));
      }
    });

    return DraggableScrollableSheet(
      controller: _controller,
      initialChildSize: kMapSheetMinExtent,
      minChildSize:     kMapSheetMinExtent,
      maxChildSize:     kMapSheetMaxExtent,
      snap:      true,
      snapSizes: const [
        kMapSheetMinExtent,
        kMapSheetMidExtent,
        kMapSheetMaxExtent,
      ],
      builder: (context, scrollController) => _SheetSurface(
        scrollController: scrollController,
        onExpand: _onExpand,
      ),
    );
  }
}

// ── Sheet surface ─────────────────────────────────────────────────────────

class _SheetSurface extends ConsumerWidget {
  final ScrollController scrollController;
  final VoidCallback onExpand;

  const _SheetSurface({
    required this.scrollController,
    required this.onExpand,
  });

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final mode = ref.watch(sheetStateNotifierProvider).mode;

    return DecoratedBox(
      decoration: const BoxDecoration(
        color: ThemeColors.surface,
        borderRadius: ThemeRadius.brSheet,
        boxShadow: ThemeShadows.modal,
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          const _DragHandle(),
          Expanded(
            child: CustomScrollView(
              controller: scrollController,
              slivers: [
                SliverToBoxAdapter(
                  child: switch (mode) {
                    SheetMode.peek =>
                      NavPeekContent(onTap: onExpand),
                    SheetMode.fullSearch =>
                      const NavFullSearchContent(),
                    SheetMode.tripOverview =>
                      NavPeekContent(onTap: onExpand),
                  },
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

void _noop() {}

// ── Drag handle ───────────────────────────────────────────────────────────

class _DragHandle extends StatelessWidget {
  const _DragHandle();

  @override
  Widget build(BuildContext context) {
    return const SizedBox(
      height: 28,
      child: Center(
        child: SizedBox(
          width: 36,
          height: 4,
          child: DecoratedBox(
            decoration: BoxDecoration(
              color: ThemeColors.borderStrong,
              borderRadius: BorderRadius.all(Radius.circular(2)),
            ),
          ),
        ),
      ),
    );
  }
}

import 'dart:async';

import 'package:here_sdk/core.dart';
import 'package:here_sdk/search.dart';
import 'package:riverpod_annotation/riverpod_annotation.dart';

import '../utils/strings.dart';
import 'nav_search_state.dart';

part 'nav_search_notifier.g.dart';

@Riverpod(keepAlive: true)
class NavSearchNotifier extends _$NavSearchNotifier {
  SearchEngine? _engine;
  Timer? _debounce;

  // Incremented on every new search. Stale callbacks compare against this and
  // drop their result if a newer search has already fired.
  int _gen = 0;

  @override
  NavSearchState build() {
    _engine = SearchEngine();
    ref.onDispose(() {
      _debounce?.cancel();
    });
    return const NavSearchState();
  }

  void setActiveField(SearchField field) {
    if (state.activeField == field) return;
    state = state.withClearedSuggestions().copyWith(activeField: field);
  }

  /// Triggers a debounced autosuggest for [query] biased around [center].
  /// Pass null for [center] to use a London default (online search only).
  void search(String query, GeoCoordinates? center) {
    _debounce?.cancel();

    if (query.trim().isEmpty) {
      _gen++;
      state = state.withClearedSuggestions();
      return;
    }

    state = state.copyWith(isLoading: true, error: null, suggestions: []);
    final gen = ++_gen;
    _debounce = Timer(
      const Duration(milliseconds: 250),
      () => _doSearch(query, center, gen),
    );
  }

  void _doSearch(String query, GeoCoordinates? center, int gen) {
    final engine = _engine;
    if (engine == null) return;

    final area = TextQueryArea.withCenter(
      center ?? GeoCoordinates(51.5074, -0.1278), // London fallback
    );
    final textQuery = TextQuery.withArea(query, area);
    final opts = SearchOptions()
      ..languageCode = LanguageCode.enGb
      ..maxItems = 7;

    engine.suggestByText(textQuery, opts, (SearchError? err, List<Suggestion>? results) {
      if (gen != _gen) return; // superseded by a newer search
      if (err != null) {
        state = state.copyWith(
          isLoading: false,
          error: NavStrings.searchError,
          suggestions: [],
        );
        return;
      }
      state = state.copyWith(
        isLoading: false,
        error: null,
        suggestions: results ?? [],
      );
    });
  }

  void selectOrigin(Suggestion s) {
    _cancel();
    state = state.withOrigin(s);
  }

  void selectDest(Suggestion s) {
    _cancel();
    state = state.withDest(s);
  }

  void clearOrigin() {
    _cancel();
    state = state.withOrigin(null);
  }

  void clearDest() {
    _cancel();
    state = state.withDest(null);
  }

  void swap() {
    _cancel();
    state = state.swapped();
  }

  void lockForRouting() {
    if (!state.isRouting) state = state.copyWith(isRouting: true);
  }

  void unlockRouting() {
    if (state.isRouting) state = state.copyWith(isRouting: false);
  }

  void reset() {
    _cancel();
    state = const NavSearchState();
  }

  void _cancel() {
    _debounce?.cancel();
    _gen++;
  }
}

import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:here_sdk/core.dart';
import 'package:here_sdk/mapview.dart';
import 'package:ukcheckpoints_api/ukcheckpoints_api.dart';
import 'package:ukcheckpoints_app/core/theme/theme.dart';
import 'package:ukcheckpoints_app/features/checkpoints/providers/checkpoint_provider.dart';
import 'package:ukcheckpoints_app/features/checkpoints/widgets/checkpoint_action_sheet_widget.dart';
import 'package:ukcheckpoints_app/features/checkpoints/widgets/nearby_checkpoint_popup.dart';
import 'package:ukcheckpoints_app/features/map/controllers/map_controller.dart';
import 'package:ukcheckpoints_app/features/map/widgets/map_bottom_sheet.dart';
import 'package:ukcheckpoints_app/features/map/widgets/map_overlay_buttons.dart';
import 'package:ukcheckpoints_app/features/map/widgets/map_search_bar.dart';
import 'package:ukcheckpoints_app/features/map/widgets/map_speed_overlay.dart';
import 'package:ukcheckpoints_app/features/navigation/models/sheet_state.dart';
import 'package:ukcheckpoints_app/features/navigation/providers/sheet_state_provider.dart';

class MapScreen extends ConsumerStatefulWidget {
  const MapScreen({super.key});

  @override
  ConsumerState<MapScreen> createState() => _MapScreenState();
}

class _MapScreenState extends ConsumerState<MapScreen> {
  MapImage? _activeIcon;
  MapImage? _inactiveIcon;
  MapImage? _policeIcon;
  MapImage? _unknownIcon;

  List<Checkpoint>? _pendingCheckpoints;

  // The first confirmed GPS fix. HereMap is not rendered until this is set.
  GeoCoordinates? _initialLocation;

  @override
  void initState() {
    super.initState();
    unawaited(_loadIcons());
  }

  Future<void> _loadIcons() async {
    _activeIcon = await _loadImage('assets/images/marker_active.png');
    _inactiveIcon = await _loadImage('assets/images/marker_inactive.png');
    _policeIcon = await _loadImage('assets/images/marker_police.png');
    _unknownIcon = await _loadImage('assets/images/marker_unknown.png');
    if (!mounted) return;

    final checkpoints =
        _pendingCheckpoints ??
        ref.read(checkpointNotifierProvider).value?.checkpoints ??
        [];
    if (checkpoints.isNotEmpty) {
      _updateMapCheckpoints(checkpoints);
      _pendingCheckpoints = null;
    }
  }

  void _updateMapCheckpoints(List<Checkpoint> checkpoints) {
    final active = _activeIcon;
    final inactive = _inactiveIcon;
    final police = _policeIcon;
    final unknown = _unknownIcon;

    if (active == null ||
        inactive == null ||
        police == null ||
        unknown == null) {
      _pendingCheckpoints = checkpoints;
      return;
    }

    ref.read(mapControllerProvider.notifier).updateCheckpoints(checkpoints, {
      ContributionStatusEnum.ACTIVE: active,
      ContributionStatusEnum.INACTIVE: inactive,
      ContributionStatusEnum.POLICE_ALERT: police,
      ContributionStatusEnum.UNKNOWN: unknown,
    });
  }

  Future<MapImage> _loadImage(String asset) async {
    final bytes = await rootBundle.load(asset);
    return MapImage.withPixelDataAndImageFormat(
      bytes.buffer.asUint8List(),
      ImageFormat.png,
    );
  }

  void _onMapCreated(HereMapController hereMapController) {
    // Center the map instantly on the known location — no animation, no jump.
    final loc = _initialLocation;
    if (loc != null) {
      hereMapController.camera.lookAtPointWithMeasure(
        loc,
        MapMeasure(MapMeasureKind.distanceInMeters, 1200),
      );
    }

    ref.read(mapControllerProvider.notifier).setController(
      hereMapController,
      _onCheckpointTapped,
    );

    // Pre-warm _lastLocation in the controller so the next GPS update from
    // the stream doesn't trigger the fly-to animation again.
    if (loc != null) {
      ref.read(mapControllerProvider.notifier).setInitialLocation(loc);
    }

    hereMapController.camera.addListener(
      MapCameraListener((cameraState) {
        ref.read(mapBearingProvider.notifier).state =
            cameraState.orientationAtTarget.bearing;
      }),
    );
  }

  void _onCheckpointTapped(String checkpointId) {
    final checkpoints =
        ref.read(checkpointNotifierProvider).value?.checkpoints ?? [];
    final checkpoint =
        checkpoints.where((c) => c.id == checkpointId).firstOrNull;
    if (checkpoint != null && context.mounted) {
      unawaited(
        showModalBottomSheet<void>(
          context: context,
          isScrollControlled: true,
          backgroundColor: Colors.transparent,
          builder: (context) => CheckpointActionSheet(checkpoint: checkpoint),
        ),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    // First GPS fix → store initial location and trigger rebuild to show map.
    ref
      ..listen(userLocationStreamProvider, (_, next) {
        final pos = next.value;
        if (pos == null) return;
        final coords = GeoCoordinates(pos.latitude, pos.longitude);

        if (_initialLocation == null) {
          setState(() => _initialLocation = coords);
        } else {
          // Map is rendered; pass updates to the controller directly.
          ref.read(mapControllerProvider.notifier).updateLocation(coords);
        }
      })
      ..listen(checkpointNotifierProvider, (_, next) {
        next.whenData((data) {
          _updateMapCheckpoints(data.checkpoints);
        });
      });

    // Block rendering until we have a confirmed location.
    if (_initialLocation == null) {
      return const _LocationAcquiringScreen();
    }

    return Scaffold(
      body: LayoutBuilder(
        builder: (context, constraints) {
          // Pixel offset of the sheet's peek edge from the bottom of the body.
          // Overlay controls sit just above this line; the sheet slides up
          // and covers them when expanded to half or full.
          final peekEdge = constraints.maxHeight * kMapSheetMinExtent + 16;

          return Stack(
            children: [
              Listener(
                behavior: HitTestBehavior.translucent,
                onPointerDown: (_) {
                  FocusScope.of(context).unfocus();
                  // "Changed my mind": tapping the map while in full search
                  // peeks the sheet without discarding typed text.
                  if (ref.read(sheetStateNotifierProvider).mode ==
                      SheetMode.fullSearch) {
                    ref.read(sheetStateNotifierProvider.notifier).peek();
                  }
                },
                child: HereMap(onMapCreated: _onMapCreated),
              ),

              // Controls anchored just above the peek line.
              Positioned(
                bottom: peekEdge,
                right: 16,
                child: const MapOverlayButtons(),
              ),

              Positioned(
                bottom: peekEdge,
                left: 16,
                child: const MapSpeedOverlay(),
              ),

              Positioned(
                bottom: peekEdge,
                left: 0,
                right: 0,
                child: const NearbyCheckpointPopup(),
              ),

              Positioned(
                top: 0,
                left: 0,
                right: 0,
                child: MapSearchBar(
                  onCheckpointSelected: (checkpoint) {
                    ref
                        .read(mapControllerProvider.notifier)
                        .focusOnCheckpoint(checkpoint);
                  },
                ),
              ),

              // Sheet is topmost — slides up and covers controls in half/full
              // mode; transparent area passes touches through to the map.
              const Positioned.fill(child: MapBottomSheet()),
            ],
          );
        },
      ),
    );
  }
}

// ─── Splash shown while waiting for first GPS fix ─────────────

class _LocationAcquiringScreen extends StatelessWidget {
  const _LocationAcquiringScreen();

  @override
  Widget build(BuildContext context) {
    return const Scaffold(
      backgroundColor: ThemeColors.bg,
      body: Center(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            SizedBox(
              width: 22,
              height: 22,
              child: CircularProgressIndicator(
                strokeWidth: 2,
                color: ThemeColors.accent,
              ),
            ),
            SizedBox(height: ThemeSpacing.sp3),
            Text(
              'Acquiring location…',
              style: TextStyle(
                fontFamily: ThemeFonts.ui,
                fontSize: 13,
                color: ThemeColors.textTertiary,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

