35	@Riverpod(keepAlive: true)
36	class MapController extends _$MapController {
37	  LocationIndicator? _locationIndicator;
38	  GeoCoordinates? _lastLocation;
39	
40	  // Keyed by checkpointId for O(1) diffing.
41	  final Map<String, MapMarker> _markerById = {};
42	
43	  PolygonPrefetcher? _prefetcher;
44	  bool _hasPrefetched = false;
45	
46	  @override
47	  HereMapController? build() {
48	    ref.onDispose(() {
49	      _locationIndicator = null;
50	      _markerById.clear();
51	    });
52	    return null;
53	  }
54	
55	  void setController(
56	    HereMapController controller,
57	    void Function(String) onCheckpointTap,
58	  ) {
59	    state = controller;
60	    _setupLocationIndicator(controller);
61	    _setupGestureListeners(controller, onCheckpointTap);
62	    unawaited(_loadAndApplyPreferences());
63	  }
