65	  Future<void> _loadAndApplyPreferences() async {
66	    final prefs = ref.read(mapPreferencesRepositoryProvider);
67	    final schemeName = await prefs.getMapScheme();
68	    final trafficOn = await prefs.isTrafficEnabled();
69	    final transitOn = await prefs.isPublicTransitEnabled();
70	    final camerasOn = await prefs.isSafetyCamerasEnabled();
71	    final lightsOn = await prefs.isTrafficLightsEnabled();
72	    final zonesOn = await prefs.isCongestionZonesEnabled();
73	    final exitsOn = await prefs.isRoadExitLabelsEnabled();
74	
75	    final scheme = MapScheme.values.firstWhere(
76	      (s) => s.name == schemeName,
77	      orElse: () => MapScheme.normalDay,
78	    );
79	
80	    ref.read(isTrafficEnabledProvider.notifier).state = trafficOn;
81	    ref.read(isPublicTransitEnabledProvider.notifier).state = transitOn;
82	    ref.read(isSafetyCamerasEnabledProvider.notifier).state = camerasOn;
83	    ref.read(isTrafficLightsEnabledProvider.notifier).state = lightsOn;
84	    ref.read(isCongestionZonesEnabledProvider.notifier).state = zonesOn;
85	    ref.read(isRoadExitLabelsEnabledProvider.notifier).state = exitsOn;
86	
87	    if (state != null) {
88	      setMapScheme(scheme, refocus: true);
89	    }
90	  }
91	
92	  void _setupGestureListeners(
93	    HereMapController controller,
94	    void Function(String) onCheckpointTap,
95	  ) {
96	    controller.gestures.tapListener = TapListener((Point2D point) {
97	      final current = state;
98	      if (current == null) return;
99	
100	      current.pick(
101	        MapSceneMapPickFilter([MapSceneMapPickFilterContentType.mapItems]),
102	        Rectangle2D(point, Size2D(40, 40)),
103	        (MapPickResult? result) {
104	          final marker = result?.mapItems?.markers.firstOrNull;
105	          if (marker == null) return;
106	          final id = marker.metadata?.getString('checkpointId');
107	          if (id != null) onCheckpointTap(id);
108	        },
109	      );
110	    });
111	  }
112	
113	  void _setupLocationIndicator(HereMapController controller) {
114	    _locationIndicator = LocationIndicator.withMapView(controller)
115	      ..locationIndicatorStyle = LocationIndicatorIndicatorStyle.pedestrian
116	      ..enable(controller);
117	  }
118	
119	  // Called once from _onMapCreated when the map is already centered on the
120	  // user's position. Sets _lastLocation so updateLocation won't trigger the
121	  // fly animation on the next GPS update.
122	  void setInitialLocation(GeoCoordinates coordinates) {
123	    _lastLocation = coordinates;
124	    _locationIndicator?.updateLocation(Location.withCoordinates(coordinates));
125	    _prefetchAroundLocation(coordinates);
126	  }
127	
128	  void updateLocation(GeoCoordinates coordinates) {
129	    final isFirstLocation = _lastLocation == null;
130	    _lastLocation = coordinates;
131	    _locationIndicator?.updateLocation(Location.withCoordinates(coordinates));
132	
133	    if (isFirstLocation) {
134	      focusOnUserLocation();
135	      _prefetchAroundLocation(coordinates);
136	    }
137	  }
138	
139	  void _prefetchAroundLocation(GeoCoordinates coords) {
140	    final engine = SDKNativeEngine.sharedInstance;
141	    if (engine == null || _hasPrefetched) return;
142	    _hasPrefetched = true;
143	
144	    _prefetcher ??= PolygonPrefetcher(engine);
145	    final polygon = GeoPolygon.withGeoCircle(GeoCircle(coords, 3000));
146	    _prefetcher!.prefetch(
147	      polygon,
148	      PrefetchStatusListener(
149	        (_) {},
150	        (error) {
151	          if (error != null) {
152	            AppLogger.error(
153	              'Tile prefetch failed',
154	              error: error,
155	              stackTrace: StackTrace.current,
156	            );
157	          }
158	        },
159	      ),
160	    );
161	  }
162	
163	  void focusOnUserLocation() {
164	    _animateTo(_lastLocation);
165	  }
166	
167	  void focusOnCoordinates(GeoCoordinates coords) {
168	    _animateTo(coords);
169	  }
170	
171	  void _animateTo(GeoCoordinates? coords) {
172	    if (coords == null || state == null) return;
173	    final animation = MapCameraAnimationFactory.flyToWithZoom(
174	      GeoCoordinatesUpdate(coords.latitude, coords.longitude),
175	      MapMeasure(MapMeasureKind.distanceInMeters, 1000),
176	      0,
177	      const Duration(milliseconds: 800),
178	    );
179	    state!.camera.startAnimation(animation);
180	  }
181	
182	  void resetOrientationToNorth() {
183	    final controller = state;
184	    if (controller == null) return;
185	
186	    final cameraState = controller.camera.state;
187	    final animation = MapCameraAnimationFactory.flyToWithOrientationAndZoom(
188	      GeoCoordinatesUpdate(
189	        cameraState.targetCoordinates.latitude,
190	        cameraState.targetCoordinates.longitude,
191	      ),
192	      GeoOrientationUpdate(0, cameraState.orientationAtTarget.tilt),
193	      MapMeasure(
194	        MapMeasureKind.distanceInMeters,
195	        cameraState.distanceToTargetInMeters,
196	      ),
197	      0,
198	      const Duration(milliseconds: 600),
199	    );
200	    controller.camera.startAnimation(animation);
201	
202	    ref.read(mapBearingProvider.notifier).state = 0.0;
203	  }
204	
205	  // Builds a new MapMarker for a checkpoint, embedding its status in metadata
206	  // so the diff logic can detect when the icon needs refreshing.
207	  MapMarker _buildMarker(
208	    Checkpoint checkpoint,
209	    Map<ContributionStatusEnum, MapImage> icons,
210	  ) {
211	    final status = checkpoint.contributions.isNotEmpty
212	        ? checkpoint.contributions.first.status
213	        : ContributionStatusEnum.UNKNOWN;
214	    final icon = icons[status] ?? icons[ContributionStatusEnum.UNKNOWN]!;
215	    return MapMarker(
216	      GeoCoordinates(
217	        checkpoint.latitude.toDouble(),
218	        checkpoint.longitude.toDouble(),
219	      ),
220	      icon,
221	    )..metadata = (Metadata()
222	      ..setString('checkpointId', checkpoint.id)
223	      ..setString('status', status.name));
224	  }
225	
226	  ContributionStatusEnum _statusFor(Checkpoint checkpoint) =>
227	      checkpoint.contributions.isNotEmpty
228	          ? checkpoint.contributions.first.status
229	          : ContributionStatusEnum.UNKNOWN;
230	
231	  // Diffs the current marker set against the incoming checkpoints:
232	  // only removes stale markers and adds new/changed ones, in batches.
233	  void updateCheckpoints(
234	    List<Checkpoint> checkpoints,
235	    Map<ContributionStatusEnum, MapImage> icons,
236	  ) {
237	    final controller = state;
238	    if (controller == null) return;
239	
240	    final desired = {for (final c in checkpoints) c.id: c};
241	
242	    // Remove markers no longer needed.
243	    final staleIds = _markerById.keys
244	        .where((id) => !desired.containsKey(id))
245	        .toList();
246	    if (staleIds.isNotEmpty) {
247	      controller.mapScene.removeMapMarkers(
248	        staleIds.map((id) => _markerById[id]!).toList(),
249	      );
250	      staleIds.forEach(_markerById.remove);
251	    }
252	
253	    // Add new markers and refresh any whose status changed.
254	    final toAdd = <MapMarker>[];
255	    for (final checkpoint in checkpoints) {
256	      final existing = _markerById[checkpoint.id];
257	      if (existing != null) {
258	        final currentStatus = existing.metadata?.getString('status');
259	        if (currentStatus == _statusFor(checkpoint).name) continue;
260	        // Status changed — replace.
261	        controller.mapScene.removeMapMarker(existing);
262	        _markerById.remove(checkpoint.id);
263	      }
264	      final marker = _buildMarker(checkpoint, icons);
265	      toAdd.add(marker);
266	      _markerById[checkpoint.id] = marker;
267	    }
268	    if (toAdd.isNotEmpty) {
269	      controller.mapScene.addMapMarkers(toAdd);
270	    }
271	  }
