273	  void setMapScheme(MapScheme scheme, {bool refocus = false}) {
274	    ref.read(currentMapSchemeProvider.notifier).state = scheme;
275	
276	    unawaited(
277	      ref.read(mapPreferencesRepositoryProvider).setMapScheme(scheme.name),
278	    );
279	
280	    final coordinates = refocus ? _lastLocation : null;
281	
282	    final options = MapSceneLoadOptionsBuilder().withMapScheme(scheme).build();
283	    state?.mapScene.loadScene(options, (MapError? error) {
284	      if (error != null) {
285	        AppLogger.error(
286	          'Map scene load failed',
287	          error: error,
288	          stackTrace: StackTrace.current,
289	        );
290	        return;
291	      }
292	      _reapplyFeatures();
293	      if (coordinates != null) {
294	        _animateTo(coordinates);
295	      }
296	    });
297	  }
298	
299	  void _reapplyFeatures() {
300	    final controller = state;
301	    if (controller == null) return;
302	
303	    final scheme = ref.read(currentMapSchemeProvider);
304	    if (scheme == MapScheme.satellite) return;
305	
306	    final trafficOn = ref.read(isTrafficEnabledProvider);
307	    final transitOn = ref.read(isPublicTransitEnabledProvider);
308	    final camerasOn = ref.read(isSafetyCamerasEnabledProvider);
309	    final lightsOn = ref.read(isTrafficLightsEnabledProvider);
310	    final zonesOn = ref.read(isCongestionZonesEnabledProvider);
311	    final exitsOn = ref.read(isRoadExitLabelsEnabledProvider);
312	
313	    if (trafficOn) {
314	      controller.mapScene.enableFeatures({
315	        MapFeatures.trafficFlow: MapFeatureModes.trafficFlowWithFreeFlow,
316	        MapFeatures.trafficIncidents: MapFeatureModes.trafficIncidentsAll,
317	      });
318	    }
319	    if (transitOn) {
320	      controller.mapScene.enableFeatures({
321	        MapFeatures.publicTransit: MapFeatureModes.publicTransitAll,
322	      });
323	    }
324	    if (camerasOn) {
325	      controller.mapScene.enableFeatures({
326	        MapFeatures.safetyCameras: MapFeatureModes.safetyCamerasAll,
327	      });
328	    }
329	    if (lightsOn) {
330	      controller.mapScene.enableFeatures({
331	        MapFeatures.trafficLights: MapFeatureModes.trafficLightsAll,
332	      });
333	    }
334	    if (zonesOn) {
335	      controller.mapScene.enableFeatures({
336	        MapFeatures.congestionZones: MapFeatureModes.congestionZonesAll,
337	      });
338	    }
339	    if (exitsOn) {
340	      controller.mapScene.enableFeatures({
341	        MapFeatures.roadExitLabels: MapFeatureModes.roadExitLabelsAll,
342	      });
343	    }
344	  }
345	
