347	    final newValue = !ref.read(isTrafficEnabledProvider);
348	    ref.read(isTrafficEnabledProvider.notifier).state = newValue;
349	
350	    unawaited(
351	      ref.read(mapPreferencesRepositoryProvider).setTrafficEnabled(newValue),
352	    );
353	
354	    final controller = state;
355	    if (controller == null) return;
356	
357	    if (ref.read(currentMapSchemeProvider) == MapScheme.satellite) return;
358	
359	    if (newValue) {
