import 'nav_search_state.dart';

part 'nav_search_notifier.g.dart';

@Riverpod(keepAlive: true)
class NavSearchNotifier extends _$NavSearchNotifier {
  SearchEngine? _engine;
  Timer? _debounce;

  // Incremented on every new search. Stale callbacks compare against this and
  // drop their result if a newer search has already fired.
  int _gen = 0;

  @override
  NavSearchState build() {
    _engine = SearchEngine();
    ref.onDispose(() {
      _debounce?.cancel();
    });
    return NavSearchState();
  }

  void setActiveField(SearchField field) {
    if (state.activeField == field) return;
    state = state.withClearedSuggestions().copyWith(activeField: field);
  }

  /// Triggers a debounced autosuggest for [query] biased around [center].
  /// Pass null for [center] to use a London default (online search only).
  void search(String query, GeoCoordinates? center) {
    _debounce?.cancel();

    if (query.trim().isEmpty) {
      _gen++;
      state = state.withClearedSuggestions();
      return;
    }

    state = state.copyWith(isLoading: true, error: null, suggestions: []);
    final gen = ++_gen;
    _debounce = Timer(
      const Duration(milliseconds: 250),
      () => _doSearch(query, center, gen),
    );
  }

  void _doSearch(String query, GeoCoordinates? center, int gen) {
    final engine = _engine;
    if (engine == null) return;

    final area = TextQueryArea.withCenter(
      center ?? GeoCoordinates(51.5074, -0.1278), // London fallback
    );
    final textQuery = TextQuery.withArea(query, area);
    final opts = SearchOptions()
      ..languageCode = LanguageCode.enGb
      ..maxItems = 7;

    engine.suggestByText(textQuery, opts, (SearchError? err, List<Suggestion>? results) {
      if (gen != _gen) return; // superseded by a newer search
      if (err != null) {
        state = state.copyWith(
          isLoading: false,
          error: NavStrings.searchError,
          suggestions: [],
        );
        return;
      }
      state = state.copyWith(
        isLoading: false,
        error: null,
        suggestions: results ?? [],
      );
    });
  }

  void selectOrigin(Suggestion s) {
    _cancel();
    state = state.withOrigin(s);
  }

  void selectDest(Suggestion s) {
    _cancel();
    state = state.withDest(s);
  }

  void clearOrigin() {
    _cancel();
    state = state.withOrigin(null);
  }

  void clearDest() {
    _cancel();
    state = state.withDest(null);
  }

  void swap() {
    _cancel();
    state = state.swapped();
  }

  void lockForRouting() {
    if (!state.isRouting) state = state.copyWith(isRouting: true);
  }

  void unlockRouting() {
    if (state.isRouting) state = state.copyWith(isRouting: false);
  }

  void setError(String? message) {
    if (state.error != message) state = state.copyWith(error: message);
  }

  void reset() {
    _cancel();
    state = NavSearchState();
  }

  void _cancel() {
    _debounce?.cancel();
    _gen++;
  }
}

import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:ukcheckpoints_app/core/theme/theme.dart';
import 'package:ukcheckpoints_app/features/navigation/models/sheet_state.dart';
import 'package:ukcheckpoints_app/features/navigation/providers/sheet_state_provider.dart';
import 'package:ukcheckpoints_app/features/navigation/sheets/full_search_content.dart';
import 'package:ukcheckpoints_app/features/navigation/sheets/peek_content.dart';
import 'package:ukcheckpoints_app/features/navigation/sheets/trip_overview_content.dart';

const double kMapSheetMinExtent  = 0.12;
const double kMapSheetMidExtent  = 0.50;
const double kMapSheetMaxExtent  = 0.92;

// Tolerance for snapped-position detection from the controller listener.
const double _snapTol = 0.02;

class MapBottomSheet extends ConsumerStatefulWidget {
  const MapBottomSheet({super.key});

  @override
  ConsumerState<MapBottomSheet> createState() => _MapBottomSheetState();
}

class _MapBottomSheetState extends ConsumerState<MapBottomSheet> {
  final _controller = DraggableScrollableController();

  @override
  void initState() {
    super.initState();
    _controller.addListener(_onControllerChanged);
  }

  @override
  void dispose() {
    _controller
      ..removeListener(_onControllerChanged)
      ..dispose();
    super.dispose();
  }

  // ── Drag → provider sync ──────────────────────────────────────────────────
  // When the user manually drags the sheet to a snap point, mirror that into
  // the provider so the rendered content stays correct.
  void _onControllerChanged() {
    if (!_controller.isAttached) return;
    final s = _controller.size;
    final notifier = ref.read(sheetStateNotifierProvider.notifier);
    if ((s - kMapSheetMinExtent).abs() < _snapTol) {
      notifier.peek();
    } else if ((s - kMapSheetMaxExtent).abs() < _snapTol) {
      notifier.expand();
    } else if ((s - kMapSheetMidExtent).abs() < _snapTol) {
      notifier.showTripOverview();
    }
  }

  // ── Provider → animation ──────────────────────────────────────────────────
  Future<void> _animateTo(double extent) async {
    if (!_controller.isAttached) return;
    if ((_controller.size - extent).abs() < _snapTol) return;
    await _controller.animateTo(
      extent,
      duration: ThemeMotion.medium,
      curve: ThemeMotion.smooth,
    );
  }

  void _onExpand() {
    ref.read(sheetStateNotifierProvider.notifier).expand();
    unawaited(_animateTo(kMapSheetMaxExtent));
  }

  // ── Build ─────────────────────────────────────────────────────────────────

  @override
  Widget build(BuildContext context) {
    // Drive sheet animation whenever the provider mode changes.
    ref.listen<SheetState>(sheetStateNotifierProvider, (prev, next) {
      if (prev?.mode == next.mode) return;
      switch (next.mode) {
        case SheetMode.peek:
          unawaited(_animateTo(kMapSheetMinExtent));
        case SheetMode.fullSearch:
          unawaited(_animateTo(kMapSheetMaxExtent));
        case SheetMode.tripOverview:
          unawaited(_animateTo(kMapSheetMidExtent));
      }
    });

    return DraggableScrollableSheet(
      controller: _controller,
      initialChildSize: kMapSheetMinExtent,
      minChildSize:     kMapSheetMinExtent,
      maxChildSize:     kMapSheetMaxExtent,
      snap:      true,
      snapSizes: const [
        kMapSheetMinExtent,
        kMapSheetMidExtent,
        kMapSheetMaxExtent,
      ],
      builder: (context, scrollController) => _SheetSurface(
        scrollController: scrollController,
        onExpand: _onExpand,
      ),
    );
  }
}

// ── Sheet surface ─────────────────────────────────────────────────────────

class _SheetSurface extends ConsumerWidget {
  final ScrollController scrollController;
  final VoidCallback onExpand;

  const _SheetSurface({
    required this.scrollController,
    required this.onExpand,
  });

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final mode = ref.watch(sheetStateNotifierProvider).mode;

    return DecoratedBox(
      decoration: const BoxDecoration(
        color: ThemeColors.surface,
        borderRadius: ThemeRadius.brSheet,
        boxShadow: ThemeShadows.modal,
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          const _DragHandle(),
          Expanded(
            child: CustomScrollView(
              controller: scrollController,
              slivers: [
                SliverToBoxAdapter(
                  child: switch (mode) {
                    SheetMode.peek =>
                      NavPeekContent(onTap: onExpand),
                    SheetMode.fullSearch =>
                      const NavFullSearchContent(),
                    SheetMode.tripOverview =>
                      const NavTripOverviewContent(),
                  },
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

// ── Drag handle ───────────────────────────────────────────────────────────

class _DragHandle extends StatelessWidget {
  const _DragHandle();

  @override
  Widget build(BuildContext context) {
    return const SizedBox(
      height: 28,
      child: Center(
        child: SizedBox(
          width: 36,
          height: 4,
          child: DecoratedBox(
            decoration: BoxDecoration(
              color: ThemeColors.borderStrong,
              borderRadius: BorderRadius.all(Radius.circular(2)),
            ),
          ),
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:ukcheckpoints_app/core/theme/theme.dart';
import 'package:ukcheckpoints_app/features/navigation/maneuvers/maneuver_icons.dart';
import 'package:ukcheckpoints_app/features/navigation/models/navigation_phase.dart';
import 'package:ukcheckpoints_app/features/navigation/providers/nav_state_provider.dart';
import 'package:ukcheckpoints_app/features/navigation/search/nav_search_notifier.dart';
import 'package:ukcheckpoints_app/features/navigation/utils/strings.dart';
import 'package:ukcheckpoints_app/features/navigation/utils/uk_formatter.dart';

class NavTripOverviewContent extends ConsumerWidget {
  const NavTripOverviewContent({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final phase = ref.watch(navStateNotifierProvider);
    if (phase is! TripOverview) return const SizedBox.shrink();

    final route  = phase.route;
    final search = ref.watch(navSearchNotifierProvider);
    final dest   = search.selectedDest;

    final destName    = dest?.title ?? NavStrings.goingToHint;
    final destAddress = dest?.place?.address.addressText;

    final dur       = route.duration;
    final hours     = dur.inHours;
    final mins      = dur.inMinutes.remainder(60);
    final durationStr = hours > 0 ? '${hours}h ${mins}m' : '$mins min';

    final eta    = DateTime.now().add(dur);
    final etaStr = TimeOfDay.fromDateTime(eta).format(context);

    final distStr = UkFormatter.formatDistance(route.lengthInMeters);

    // First maneuver from the first section (skip the depart maneuver at idx 0
    // if the section has more than one — it's always "Depart").
    final maneuvers = route.sections.firstOrNull?.maneuvers ?? [];
    final firstTurn = maneuvers.length > 1 ? maneuvers[1] : maneuvers.firstOrNull;

    return Padding(
      padding: const EdgeInsets.fromLTRB(
        ThemeSpacing.sp4,
        ThemeSpacing.sp2,
        ThemeSpacing.sp4,
        ThemeSpacing.sp5,
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        mainAxisSize: MainAxisSize.min,
        children: [
          // ── Destination ────────────────────────────────────────────────────
          Row(
            children: [
              const Icon(
                Icons.location_on,
                size: 18,
                color: ThemeColors.accent,
              ),
              const SizedBox(width: ThemeSpacing.sp2),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      destName,
                      style: ThemeText.titleMedium,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                    ),
                    if (destAddress != null)
                      Text(
                        destAddress,
                        style: ThemeText.subheadline.copyWith(
                          color: ThemeColors.textSecondary,
                        ),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                      ),
                  ],
                ),
              ),
            ],
          ),

          const SizedBox(height: ThemeSpacing.sp4),

          // ── Summary chips ──────────────────────────────────────────────────
          IntrinsicHeight(
            child: Row(
              children: [
                _InfoChip(
                  label: NavStrings.arrivalLabel,
                  value: etaStr,
                ),
                const _Divider(),
                _InfoChip(
                  label: NavStrings.durationLabel,
                  value: durationStr,
                ),
                const _Divider(),
                _InfoChip(
                  label: NavStrings.distanceLabel,
                  value: distStr,
                ),
              ],
            ),
          ),

          // ── First turn preview ─────────────────────────────────────────────
          if (firstTurn != null) ...[
            const SizedBox(height: ThemeSpacing.sp3),
            DecoratedBox(
              decoration: BoxDecoration(
                color: ThemeColors.surfaceContainer,
                borderRadius: ThemeRadius.brSmall,
              ),
              child: Padding(
                padding: const EdgeInsets.symmetric(
                  horizontal: ThemeSpacing.sp3,
                  vertical: ThemeSpacing.sp3,
                ),
                child: Row(
                  children: [
                    Image.asset(
                      maneuverIconPath(firstTurn.action),
                      width:  28,
                      height: 28,
                      color:  ThemeColors.textPrimary,
                    ),
                    const SizedBox(width: ThemeSpacing.sp3),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            NavStrings.nextTurnLabel,
                            style: ThemeText.labelSmall.copyWith(
                              color: ThemeColors.textTertiary,
                            ),
                          ),
                          Text(
                            firstTurn.text,
                            style: ThemeText.bodyMedium,
                            maxLines: 2,
                            overflow: TextOverflow.ellipsis,
                          ),
                        ],
                      ),
                    ),
                    const SizedBox(width: ThemeSpacing.sp2),
                    Text(
                      UkFormatter.formatDistance(firstTurn.lengthInMeters),
                      style: ThemeText.callout.copyWith(
                        color: ThemeColors.textSecondary,
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ],

          const SizedBox(height: ThemeSpacing.sp4),

          // ── Actions ────────────────────────────────────────────────────────
          Row(
            children: [
              Expanded(
                child: OutlinedButton(
                  onPressed: () =>
                      ref.read(navStateNotifierProvider.notifier).closeTrip(),
                  child: const Text(NavStrings.closeCta),
                ),
              ),
              const SizedBox(width: ThemeSpacing.sp3),
              Expanded(
                flex: 2,
                child: FilledButton(
                  onPressed: () {
                    final p = ref.read(navStateNotifierProvider);
                    if (p is! TripOverview) return;
                    ref
                        .read(navStateNotifierProvider.notifier)
                        .startDrive(p.route);
                  },
                  child: const Text(NavStrings.startDriveCta),
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }
}

// ── Sub-widgets ────────────────────────────────────────────────────────────

class _InfoChip extends StatelessWidget {
  final String label;
  final String value;

  const _InfoChip({required this.label, required this.value});

  @override
  Widget build(BuildContext context) {
    return Expanded(
      child: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Text(
            value,
            style: ThemeText.titleMedium,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
          ),
          Text(
            label,
            style: ThemeText.labelSmall.copyWith(
              color: ThemeColors.textTertiary,
            ),
          ),
        ],
      ),
    );
  }
}

class _Divider extends StatelessWidget {
  const _Divider();

  @override
  Widget build(BuildContext context) {
    return const SizedBox(
      width: 1,
      height: 36,
      child: DecoratedBox(
        decoration: BoxDecoration(color: ThemeColors.border),
      ),
    );
  }
}

