    snap:      true,
    snapSizes: [
      kMapSheetMinExtent,
      if (allowMid) kMapSheetMidExtent,
      kMapSheetMaxExtent,
    ],
    builder: (context, scrollController) => _SheetSurface(
      scrollController: scrollController,
      onExpand: _onExpand,
    ),
  );
}

